/**
 * The console's one width function (console/width.ts) and the Unicode table it reads (console/width-table.ts,
 * generated by tools/unicode/generate-width-table.mjs). Every expected width below is a literal written here, never
 * computed with the function under test, so a mismeasured cluster fails even where the function agrees with itself.
 */
import { createHash } from 'node:crypto';
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { afterAll, describe, expect, it } from 'vitest';
import { runBounded } from '@tools/testing/subprocess.js';
import { clusterWidth, graphemes, pad, stringWidth, truncate, truncateMiddle } from '../src/console/width.js';
import * as table from '../src/console/width-table.js';
import { words, wrapTokens } from '../src/render.js';

const repository = resolve(import.meta.dirname, '../../..');
const generator = resolve(repository, 'tools/unicode/generate-width-table.mjs');
const vendored = resolve(repository, 'tools/unicode/16.0.0');
const committed = resolve(import.meta.dirname, '../src/console/width-table.ts');
const SOURCE_PATHS = [
  'ucd/EastAsianWidth.txt',
  'ucd/emoji/emoji-data.txt',
  'ucd/extracted/DerivedGeneralCategory.txt',
] as const;
interface Generator {
  build(texts: Record<string, string>): string;
  tables(texts: Record<string, string>): Record<string, [number, number][]>;
}
const load = async (): Promise<Generator> => (await import(pathToFileURL(generator).href)) as Generator;
const sha = (bytes: Buffer): string => createHash('sha256').update(bytes).digest('hex');

const temporary: string[] = [];
afterAll(() => {
  for (const path of temporary) rmSync(path, { recursive: true, force: true });
});

describe('cluster widths', () => {
  const table: readonly (readonly [string, number])[] = [
    // all-zero clusters
    ['\uFE0F', 0],
    ['\uFE0E', 0],
    ['\u200D', 0],
    ['\u0301', 0],
    ['\u20E3', 0],
    ['\x1b', 0],
    ['\x7f', 0],
    // a selector after a non-emoji base does not widen it
    ['a\uFE0F', 1],
    ['A\uFE0F', 1],
    ['用\uFE0F', 2],
    ['é\uFE0F', 1],
    // text and emoji presentation
    ['❤', 1],
    ['❤\uFE0F', 2],
    ['❤\uFE0E', 1],
    ['\u{1F680}', 2],
    ['\u{1F680}\uFE0E', 2],
    // keycaps
    ['1\uFE0F\u20E3', 2],
    ['#\uFE0F\u20E3', 2],
    // modifiers and ZWJ sequences
    ['☝\u{1F3FD}', 2],
    ['\u{1F44D}\u{1F3FD}', 2],
    ['👨\u200D👩\u200D👧', 2],
    ['🏳\uFE0F\u200D🌈', 2],
    ['👩🏽\u200D💻', 2],
    // flags
    ['🇺🇸', 2],
    ['🇺', 1],
    // emoji outside any hand-written range
    ['🚀', 2],
    ['🧿', 2],
    ['🛸', 2],
    ['\u{1FAE0}', 2],
    // combining
    ['e\u0301', 1],
  ];
  it.each(table)('%j is %i columns', (cluster, width) => {
    expect(graphemes(cluster)).toHaveLength(1);
    expect(clusterWidth(cluster)).toBe(width);
    expect(stringWidth(cluster)).toBe(width);
  });

  it('ascii is its length', () => {
    expect(stringWidth('ia doctor --json')).toBe(16);
    expect(stringWidth('')).toBe(0);
  });
  it('CJK counts two', () => {
    expect(stringWidth('用户项目')).toBe(8);
    expect(stringWidth('한')).toBe(2);
    expect(stringWidth('Ａ')).toBe(2);
  });
  it('SGR is invisible', () => {
    expect(stringWidth('\x1b[31mab\x1b[0m')).toBe(2);
    expect(stringWidth('\x1b[1;36mia\x1b[0m 用')).toBe(5);
  });
  it('control characters count zero', () => {
    expect(stringWidth('a\x00b\x07c\x9b')).toBe(3);
    expect(stringWidth('a\tb\nc')).toBe(3);
  });
});

describe('truncation and padding', () => {
  it('truncate never splits a cluster and ends with an ellipsis', () => {
    expect(truncate('ab🚀cd', 4)).toBe('ab…');
    expect(truncate('ab🚀cd', 5)).toBe('ab🚀…');
    expect(truncate('ab🚀cd', 6)).toBe('ab🚀cd');
    expect(truncate('ab🚀cd', 4, true)).toBe('ab~');
    // A ZWJ sequence is cut whole or kept whole.
    expect(truncate('x👨\u200D👩\u200D👧yz', 3)).toBe('x…');
    expect(truncate('x👨\u200D👩\u200D👧yz', 4)).toBe('x👨\u200D👩\u200D👧…');
    expect(truncate('abc', 0)).toBe('');
    expect(truncate('abc', 1)).toBe('…');
  });
  it('pad truncates then fills to exactly the width', () => {
    const cases: readonly { text: string; width: number; expected: string }[] = [
      { text: '用户', width: 6, expected: '用户  ' },
      { text: 'a\uFE0F', width: 3, expected: 'a\uFE0F  ' },
      { text: '\uFE0F', width: 2, expected: '\uFE0F  ' },
      { text: 'abcdef', width: 4, expected: 'abc…' },
      { text: '用户项目', width: 5, expected: '用户…' },
      { text: '用户项目', width: 6, expected: '用户… ' },
      { text: '', width: 3, expected: '   ' },
    ];
    for (const { text, width, expected } of cases) expect(pad(text, width)).toBe(expected);
  });
  it('truncateMiddle keeps the head and the last segments', () => {
    // Built from parts, so this file holds no literal drive path.
    const path = ['C:', '用户', '项目', 'inventarch', 'notes'].join('\\');
    expect(truncateMiddle(path, 40)).toBe(path);
    expect(truncateMiddle(path, 21)).toBe(['C:', '…', 'inventarch', 'notes'].join('\\'));
    expect(truncateMiddle(path, 26)).toBe(['C:', '…', '项目', 'inventarch', 'notes'].join('\\'));
    expect(truncateMiddle(path, 21, true)).toBe(['C:', '~', 'inventarch', 'notes'].join('\\'));
    expect(truncateMiddle('/srv/用户/项目/inventarch/notes', 20)).toBe('/…/inventarch/notes');
  });
  it('divider alignment: every label pads to the same column', () => {
    const labels: readonly (readonly [string, number])[] = [
      ['notes', 5],
      ['用户项目', 8],
      ['🚀 launch', 9],
      ['👨\u200D👩\u200D👧 family', 9],
      ['\uFE0F', 0],
      ['a\uFE0F', 1],
      ['🇺🇸 flag', 7],
      ['❤\uFE0F ok', 5],
      ['e\u0301te\u0301', 3],
      ['한국어', 6],
    ];
    for (const [label, expected] of labels) expect(pad(label, 20)).toBe(label + ' '.repeat(20 - expected));
  });
});

describe('render.ts measures with the same function', () => {
  it('render output is unchanged for ASCII', () => {
    expect(wrapTokens(words('one two three four'), 0, { color: false, ascii: false, width: 9 })).toEqual([
      'one two',
      'three',
      'four',
    ]);
  });
  it('wide words wrap at their display width', () => {
    expect(wrapTokens(words('用户 项目 ab'), 0, { color: false, ascii: false, width: 9 })).toEqual(['用户 项目', 'ab']);
    expect(wrapTokens(words('用户项目 ab'), 0, { color: false, ascii: false, width: 10 })).toEqual(['用户项目', 'ab']);
  });
});

describe('the generated table', () => {
  const inSet = (set: readonly (readonly [number, number])[], point: number): boolean =>
    set.some(([first, last]) => first <= point && point <= last);
  const sets = {
    WIDE: table.WIDE,
    EMOJI_PRESENTATION: table.EMOJI_PRESENTATION,
    EMOJI: table.EMOJI,
    EMOJI_MODIFIER: table.EMOJI_MODIFIER,
    ZERO: table.ZERO,
    CONTROL: table.CONTROL,
  };
  it('ranges are sorted, non-overlapping and within the code space', () => {
    for (const ranges of Object.values(sets)) {
      expect(ranges.length).toBeGreaterThan(0);
      let previous = -1;
      for (const [first, last] of ranges) {
        expect(first).toBeGreaterThan(previous);
        expect(last).toBeGreaterThanOrEqual(first);
        expect(last).toBeLessThanOrEqual(0x10ffff);
        previous = last;
      }
    }
    expect(table.UNICODE_VERSION).toBe('16.0.0');
  });
  it('spot-checks', () => {
    expect(inSet(table.EMOJI_PRESENTATION, 0x1f680)).toBe(true);
    expect(inSet(table.EMOJI, 0x2764)).toBe(true);
    expect(inSet(table.EMOJI_PRESENTATION, 0x2764)).toBe(false);
    expect(inSet(table.EMOJI_MODIFIER, 0x1f3fd)).toBe(true);
    expect(inSet(table.WIDE, 0x4e00)).toBe(true);
    expect(inSet(table.ZERO, 0x0301)).toBe(true);
    expect(inSet(table.ZERO, 0xfe0f)).toBe(true);
    for (const ranges of Object.values(sets)) expect(inSet(ranges, 0x41)).toBe(false);
  });
  it('its header names each vendored source with its actual size and SHA-256', () => {
    const header = readFileSync(committed, 'utf8');
    for (const path of SOURCE_PATHS) {
      const bytes = readFileSync(join(vendored, path));
      expect(header).toContain(
        `//   https://www.unicode.org/Public/16.0.0/${path}\n//     ${bytes.length} bytes, sha256 ${sha(bytes)}`,
      );
    }
    expect(header).toContain('generated by tools/unicode/generate-width-table.mjs; do not edit');
    expect(header).toContain('Unicode License v3; see THIRD_PARTY_NOTICES.txt');
  });
  it('regenerates byte for byte from the vendored sources, within 32 KiB', async () => {
    const { build } = await load();
    const texts = Object.fromEntries(SOURCE_PATHS.map((path) => [path, readFileSync(join(vendored, path), 'utf8')]));
    const text = readFileSync(committed, 'utf8');
    expect(build(texts)).toBe(text);
    const size = statSync(committed).size;
    expect(size).toBeLessThanOrEqual(32 * 1024);
    expect(text).toContain(`// Emitted: ${size} bytes\n`);
  });
  it('the generator merges small excerpts into the expected ranges', async () => {
    const { build, tables } = await load();
    const fixtures = resolve(import.meta.dirname, 'fixtures/unicode');
    const texts = {
      'ucd/EastAsianWidth.txt': readFileSync(join(fixtures, 'EastAsianWidth.txt'), 'utf8'),
      'ucd/emoji/emoji-data.txt': readFileSync(join(fixtures, 'emoji-data.txt'), 'utf8'),
      'ucd/extracted/DerivedGeneralCategory.txt': readFileSync(join(fixtures, 'DerivedGeneralCategory.txt'), 'utf8'),
    };
    expect(tables(texts)).toEqual({
      WIDE: [
        [0x1100, 0x115f],
        [0x2329, 0x232a],
        [0x3000, 0x3000],
        [0xff01, 0xff60],
      ],
      EMOJI_PRESENTATION: [
        [0x231a, 0x231b],
        [0x1f680, 0x1f680],
      ],
      EMOJI: [
        [0x23, 0x23],
        [0x2a, 0x2a],
        [0x30, 0x39],
        [0x2764, 0x2764],
        [0x1f680, 0x1f680],
      ],
      EMOJI_MODIFIER: [[0x1f3fb, 0x1f3ff]],
      ZERO: [
        [0xad, 0xad],
        [0x300, 0x36f],
        [0x483, 0x489],
        [0x200b, 0x200f],
      ],
      CONTROL: [
        [0x0, 0x1f],
        [0x7f, 0x9f],
      ],
    });
    expect(build(texts)).toContain('export const EMOJI_MODIFIER: readonly Range[] = [[0x1f3fb, 0x1f3ff]];');
  });
  it('the entry point refuses a source whose byte count or hash is not the pinned one', async () => {
    const copy = (mutate: (path: string) => void): string => {
      const directory = mkdtempSync(join(tmpdir(), 'ia-unicode-'));
      temporary.push(directory);
      for (const path of SOURCE_PATHS) {
        mkdirSync(dirname(join(directory, path)), { recursive: true });
        copyFileSync(join(vendored, path), join(directory, path));
      }
      mutate(directory);
      return directory;
    };
    const longer = copy((directory) => writeFileSync(join(directory, SOURCE_PATHS[1]), '\n', { flag: 'a' }));
    const altered = copy((directory) => {
      const file = join(directory, SOURCE_PATHS[0]);
      const bytes = readFileSync(file);
      bytes[bytes.length - 2] = bytes[bytes.length - 2] === 0x41 ? 0x42 : 0x41;
      writeFileSync(file, bytes);
    });
    for (const [directory, path] of [
      [longer, SOURCE_PATHS[1]],
      [altered, SOURCE_PATHS[0]],
    ] as const) {
      const result = await runBounded(process.execPath, [generator, '--check', '--from', directory], {
        cwd: repository,
        timeoutMs: 20_000,
      });
      expect(result.status).toBe(1);
      expect(result.stderr).toContain(`${path}:`);
      expect(result.stderr).toContain('pinned');
    }
  });
});

describe('the notice ships', () => {
  it('lists THIRD_PARTY_NOTICES.txt, carries the Unicode license and is named from NOTICE', () => {
    const cli = resolve(import.meta.dirname, '..');
    const manifest = JSON.parse(readFileSync(join(cli, 'package.json'), 'utf8')) as { files: string[] };
    expect(manifest.files).toContain('THIRD_PARTY_NOTICES.txt');
    const notices = readFileSync(join(cli, 'THIRD_PARTY_NOTICES.txt'), 'utf8');
    expect(notices).toContain('UNICODE LICENSE V3');
    expect(notices).toContain('Copyright © 1991-2026 Unicode, Inc.');
    expect(notices).toContain('16.0.0');
    expect(notices).toContain('dist/console/width-table.js');
    expect(readFileSync(join(cli, 'NOTICE'), 'utf8')).toContain('THIRD_PARTY_NOTICES.txt');
  });
});
